 static void Step(GameForm f,Keys k,bool held,int count){Input i=(Input)Get(f,"input");if(held)i.KeysDown.Add(k);else i.KeysDown.Remove(k);for(int n=0;n<count;n++){StopwatchStep(f);}}
 static void StopwatchStep(GameForm f){System.Diagnostics.Stopwatch w=(System.Diagnostics.Stopwatch)Get(f,"watch");Set(f,"last",w.Elapsed.TotalSeconds-.049);Call(f,"TickGame");}
 static void Tap(GameForm f,Keys k){Step(f,k,true,1);Step(f,k,false,1);}
